const searchDshPluginCatalog = `-- name: SearchDshPluginCatalog :many
SELECT id, catalog, name, owner, url, page, category, description_en, description_zh, npm_package, npm_version, tarball_url, stars, downloads, install_hint, added_on, catalog_version, refreshed_at FROM dsh_plugin_catalog_entry
WHERE catalog = $1
  AND ($2::text = '' OR category = $2::text)
  AND (
    $3::text = ''
    OR name ILIKE '%' || $3::text || '%'
    OR npm_package ILIKE '%' || $3::text || '%'
    OR owner ILIKE '%' || $3::text || '%'
    OR description_en ILIKE '%' || $3::text || '%'
    OR description_zh ILIKE '%' || $3::text || '%'
  )
  AND (NOT $4::bool OR npm_package <> '')
ORDER BY stars DESC, downloads DESC, name ASC
LIMIT $6::int OFFSET $5::int
`

type SearchDshPluginCatalogParams struct {
	Catalog         string `json:"catalog"`
	Category        string `json:"category"`
	Query           string `json:"query"`
	InstallableOnly bool   `json:"installable_only"`
	RowOffset       int32  `json:"row_offset"`
	RowLimit        int32  `json:"row_limit"`
}

func (q *Queries) SearchDshPluginCatalog(ctx context.Context, arg SearchDshPluginCatalogParams) ([]DshPluginCatalogEntry, error) {
	rows, err := q.db.Query(ctx, searchDshPluginCatalog,
		arg.Catalog,
		arg.Category,
		arg.Query,
		arg.InstallableOnly,
		arg.RowOffset,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []DshPluginCatalogEntry{}
	for rows.Next() {
		var i DshPluginCatalogEntry
		if err := rows.Scan(
			&i.ID,
			&i.Catalog,
			&i.Name,
			&i.Owner,
			&i.Url,
			&i.Page,
			&i.Category,
			&i.DescriptionEn,
			&i.DescriptionZh,
			&i.NpmPackage,
			&i.NpmVersion,
			&i.TarballUrl,
			&i.Stars,
			&i.Downloads,
			&i.InstallHint,
			&i.AddedOn,
			&i.CatalogVersion,
			&i.RefreshedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

